722	// allocateIPNet allocates the `newCidr` in the cidrSet allocator. If the
723	// the `newCIDR` is already allocated an error is returned.
724	// In case the function returns successfully, it's up to the caller to execute
725	// the revert function provided to revert all state made. If the function
726	// returns an error the caller of this function can assume no state was
727	// modified to the given cidrSets.
728	// allocateIPNet iterates over cidrSet so a mutex must be held when calling
729	// this function.
730	func allocateIPNet(allType allocatorType, cidrSets []cidralloc.CIDRAllocator, newCidrs []*net.IPNet) (revertFunc revert.RevertFunc, err error) {
731		if len(cidrSets) == 0 {
732			// Return an error if the node tries to allocate a CIDR and
733			// we don't have a CIDR set for this CIDR type.
734			return nil, &ErrAllocatorNotFound{
735				cidr:          newCidrs,
736				allocatorType: allType,
737			}
738		}
739	
740		var revertStack revert.RevertStack
741		defer func() {
742			if err != nil {
743				// In case of an error revert all operations made up to this point
744				revertStack.Revert()
745			}
746		}()
747	
748		// Allocate newCIDR if it is in the range of any of the allocators
749		// available. 'err' will keep the error that should be returned at the end
750		// of the loop iterations.
751		for _, newCIDR := range newCidrs {
752			var isAllocated bool
753			for _, cidrSet := range cidrSets {
754				// Do not even try to allocate if the cidrSet is full or if the
755				// newCIDR does not belong to the cidrSet.
756				if !cidrSet.InRange(newCIDR) {
757					err = fmt.Errorf("allocator not configured for the requested CIDR %s", newCIDR)
758					continue
759				}
760				if cidrSet.IsFull() {
761					// We don't allow overlapping CIDRs so this will return
762					// immediately.
763					err = fmt.Errorf("allocator %s full", cidrSet)
764					return nil, err
765				}
766				isAllocated, err = cidrSet.IsAllocated(newCIDR)
767				if err != nil {
768					return nil, err
769				}
770				if isAllocated {
771					return nil, &ErrCIDRAllocated{
772						cidr: newCIDR,
773					}
774				}
775				// Try to allocate this new CIDR
776				err = cidrSet.Occupy(newCIDR)
777				if err != nil {
778					return nil, err
779				}
780				revertStack.Push(func() error {
781					// In case of a follow up error release this new allocated CIDR.
782					return cidrSet.Release(newCIDR)
783				})
784				break
785			}
786			// If we were unable to occupy the CIDRs on any allocators then return
787			// immediately as one of the CIDR allocators should be have been able
788			// to allocate this new CIDR. 'err' is set with the appropriate error.
789			if err != nil {
790				return
791			}
792		}
793	
794		return revertStack.Revert, nil
795	}
