348	// Needs n.Mutex to be held.
349	func (n *NodesPodCIDRManager) upsertLocked(node *v2.CiliumNode) {
350		cn, allocated, updateStatus, err := n.allocateNode(node)
351		if err != nil {
352			return
353		}
354		if cn == nil {
355			// no-op
356			return
357		}
358		// if allocated is false it means that we were unable to allocate
359		// a CIDR so we need to update the status of the node into k8s.
360		if !allocated && updateStatus {
361			// the n.syncNode will never fail because it's only adding elements to a
362			// map.
363			// NodesPodCIDRManager will later on sync the node into k8s by the
364			// controller defined, which keeps retrying to create the node in k8s
365			// until it succeeds.
366	
367			// If the resource version is != "" it means the object already exists
368			// in kubernetes so we should perform an update status instead of a create.
369			if cn.GetResourceVersion() != "" {
370				n.syncNode(k8sOpUpdateStatus, cn)
371			} else {
372				n.syncNode(k8sOpCreate, cn)
373			}
374			return
375		}
376		// If the resource version is != "" it means the object already exists
377		// in kubernetes so we should perform an update instead of a create.
378		if cn.GetResourceVersion() != "" {
379			n.syncNode(k8sOpUpdate, cn)
380		} else {
381			n.syncNode(k8sOpCreate, cn)
382		}
383	}
